#!/usr/bin/env node
/**
 * The two published pages, rebuilt from the registers — so neither exists only on a host.
 *
 *   npm run pages
 *   npm run pages -- --check
 *
 * WHY THIS EXISTS
 *
 * Three pages were published from this estate. One of them, docs/reference/PROVISIONING_ATLAS.html,
 * was generated by a committed script and lives in the branch. The other two — the commissioning
 * matrix and the field guide — were written into a session scratchpad, published, and never
 * committed. Their DATA was committed (MASTER_REGISTER.json, EXTERNAL_EXECUTION.json) but the pages
 * that render it were not, and a scratchpad is reclaimed when its container is.
 *
 * So two deliverables existed in exactly one place, and that place was outside the estate. Anyone
 * wanting to change a colour, fix a heading, or re-publish after a deletion would have had to write
 * the page again from nothing — with the register intact and the rendering gone. That is the same
 * class of failure this baseline has been corrected for all week, committed by the correcting.
 *
 * HOW IT WORKS
 *
 * Each page is a template carrying one `__DATA__` token. This reads the register the page renders,
 * narrows it to the fields the page actually uses, and injects it. The emitted file is exactly what
 * was published, so `--check` fails the moment a template or a register moves and the page in the
 * branch stops matching what it would render.
 *
 * The narrowing is deliberate, not an optimisation: a page should carry the fields it displays and
 * not the register's whole internal structure, so that what a viewer can read is a decision made
 * here rather than an accident of what happened to be in the JSON.
 */

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(fileURLToPath(new URL('..', import.meta.url)));
const CHECK = process.argv.includes('--check');
const read = (p) => readFileSync(join(ROOT, p), 'utf8');
const readJson = (p) => JSON.parse(read(p));

/* A `</` inside a <script type="application/json"> block would close it early. */
const embed = (o) => JSON.stringify(o).replace(/<\//g, '<\\/');

/* ── The end-to-end sequence, read out of the entry document ───────────────────────────────────
 *
 * The walkthrough page must not invent an order. `HOW-TO-USE-THIS-BUNDLE.md` already states one, in
 * the §1 diagram, and states the accesses in its §0 table — so both are parsed out of the emitted
 * document rather than restated here. If the entry document's order changes, the page's order
 * changes with it; if either shape stops being found, this refuses to build rather than quietly
 * emitting a page with an empty phase.
 */
const entryDoc = () => read('docs/deployment/HOW-TO-USE-THIS-BUNDLE.md');

const stop = (msg) => {
  console.error(`\n  ✖  ${msg}\n`);
  process.exit(2);
};

/** §0's access table: what a reader must hold before any phase starts. */
const accesses = () => {
  const guide = entryDoc();
  const section = guide.split('\n## 0.')[1]?.split('\n## 1.')[0];
  if (!section) stop('the entry document no longer has a §0 — the walkthrough reads its access table from there');
  const rows = [...section.matchAll(/^\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*$/gm)]
    .filter((m) => m[1] !== 'Access' && !/^-+$/.test(m[1]))
    .map((m) => ({ access: m[1], provesOutBy: m[2] }));
  if (rows.length < 3) stop(`only ${rows.length} access rows parsed from the entry document's §0`);
  return rows;
};

/** §1's diagram: the phases, their ranges, and the note that says what each waits on. */
const phaseOrder = () => {
  const diagram = entryDoc().split('\n## 1.')[1]?.split('```')[1];
  if (!diagram) stop('the entry document no longer carries a §1 order diagram');
  const out = [];
  for (const label of ['A', 'B', 'C', 'D', 'E']) {
    const at = diagram.indexOf(`${label}. `);
    if (at === -1) stop(`the entry document's order diagram no longer has a phase ${label}`);
    const rest = diagram.slice(at);
    const end = rest.search(/\n\s*[├└]──/);
    const block = (end === -1 ? rest : rest.slice(0, end)).trim();
    const range = block.match(/§(\d+)\s*→\s*§(\d+)/) || block.match(/Steps?\s*(\d+)\s*→\s*(\d+)/);
    const note = block.match(/\(([^)]*)\)/s);
    let title = block.split('\n')[0].replace(/\s*──.*$/, '').replace(/\s*\(.*$/, '').replace(/^[A-E]\.\s*/, '').trim();
    /* B's range sits on the diagram's next line, under the branch. Say it in the title anyway. */
    if (range && !/[§\d]/.test(title)) title += ` — ${range[0].replace(/\s+/g, ' ')}`;
    out.push({
      label,
      title,
      from: range ? Number(range[1]) : null,
      to: range ? Number(range[2]) : null,
      /* The parenthetical wraps across diagram lines, so it arrives carrying the box-drawing
       * gutter of the branches it wrapped past. Those are furniture, not words. */
      note: note ? note[1].replace(/[│├└─┐┘]/g, ' ').replace(/\s+/g, ' ').trim() : '',
      names: block.match(/The (\d+) items in ([\w.-]+)/) || null,
    });
  }
  return out;
};

/** A runbook's own section headings, narrowed to a phase's range. */
const runbookSections = (rel, prefix, from, to) => {
  const all = (read(rel).match(/^## .+$/gm) || []).map((h) => h.replace(/^## /, '').trim());
  const mine = all
    .map((h) => {
      const m = h.match(prefix);
      if (!m) return null;
      const [head, ...tail] = h.split(/\s[·—]\s/);
      return { n: Number(m[1]), id: head.trim(), title: tail.join(' — ').trim() || head.trim() };
    })
    .filter(Boolean)
    .filter((s) => (from === null || s.n >= from) && (to === null || s.n <= to));
  if (!mine.length) stop(`${rel} has no sections in the range ${from}–${to} that the entry document names`);
  return mine;
};

const PAGES = [
  {
    id: 'commissioning-matrix',
    template: 'docs/deployment/pages/commissioning-matrix.template.html',
    target: 'docs/deployment/pages/commissioning-matrix.html',
    published: 'https://claude.ai/artifact/MhwDgct75u344jbHpT84Uu',
    renders: 'docs/deployment/MASTER_REGISTER.json',
    data() {
      const m = readJson('docs/deployment/MASTER_REGISTER.json');
      return {
        totals: m.totals,
        gatingCommissioning: m.gatingCommissioning,
        items: m.items.map((i) => ({
          id: i.id, title: i.title, source: i.source, actor: i.actor, owner: i.owner,
          severity: i.severity, category: i.category, what: i.what, why: i.why,
          state: i.state, status: i.status, actions: i.actions, inputs: i.inputs,
          trigger: i.trigger, triggerEstablished: i.triggerEstablished,
          wouldEstablish: i.wouldEstablish, validation: i.validation,
          topology: i.topology, basis: i.basis,
          blockedBy: i.blockedBy, blocking: i.blocking, releasedBy: i.releasedBy,
        })),
      };
    },
  },
  {
    id: 'field-guide',
    template: 'docs/deployment/pages/field-guide.template.html',
    target: 'docs/deployment/pages/field-guide.html',
    published: 'https://claude.ai/artifact/FeCrVVzD3TmzaZfZTjvHdA',
    renders: 'docs/deployment/EXTERNAL_EXECUTION.json',
    data() {
      const d = readJson('docs/deployment/EXTERNAL_EXECUTION.json');
      const m = readJson('docs/deployment/MASTER_REGISTER.json');
      return {
        totals: d.totals,
        gating: m.gatingCommissioning || [],
        registryStandUp: d.registryStandUp,
        tracks: d.tracks.map((t) => ({
          id: t.id, title: t.title, who: t.who, access: t.access, why: t.why,
          steps: t.steps.map((s) => ({
            id: s.id, title: s.title, source: s.source, actor: s.actor, what: s.what,
            state: s.state, actions: s.actions, inputs: s.inputs, commands: s.commands,
            closesWhen: s.closesWhen, closureNotEstablished: s.closureNotEstablished,
            carryBack: s.carryBack, waitsOn: s.waitsOn, waitedOnBy: s.waitedOnBy,
          })),
        })),
      };
    },
  },
  {
    id: 'walkthrough',
    template: 'docs/deployment/pages/walkthrough.template.html',
    target: 'docs/deployment/pages/walkthrough.html',
    published: 'https://claude.ai/artifact/7jNKvSvpGHhZq6z4FnS9CL',
    renders: 'docs/deployment/HOW-TO-USE-THIS-BUNDLE.md + EXTERNAL_EXECUTION.json',
    /* This one ships inside the export and is opened from a file path, by someone who may have no
     * route out of their network. It must render with nothing fetched. The other two pages were
     * published to a host whose policy allows a font CDN; this one cannot rely on one. */
    selfContained: true,
    data() {
      const order = phaseOrder();
      const d = readJson('docs/deployment/EXTERNAL_EXECUTION.json');
      const m = readJson('docs/deployment/MASTER_REGISTER.json');
      const by = Object.fromEntries(order.map((p) => [p.label, p]));

      const RUNBOOK = {
        A: ['docs/deployment/PORTAL-TENANT-RUNBOOK.md', /^§(\d+)/],
        B: ['docs/deployment/governance/GOVERNANCE-TENANT-RUNBOOK.md', /^Step\s+(\d+)/],
        C: ['docs/deployment/NOTIFICATION-TENANT-RUNBOOK.md', /^§(\d+)/],
        D: ['docs/deployment/PORTAL-TENANT-RUNBOOK.md', /^§(\d+)/],
      };

      const phases = [
        {
          id: '0',
          title: 'Before you start',
          why: 'Four of these are accesses. If one of them is not actually there, everything after '
            + 'it fails in a way that looks like a broken script, and you will spend the afternoon '
            + 'debugging a permission.',
          waits: '',
          kind: 'gate',
          steps: [
            {
              id: '0.1',
              title: 'Check that what you received is intact',
              detail: 'Open EXPORT_MANIFEST.json beside the files. It names the commit, the file '
                + 'count and a SHA-256 for every file. Compare a handful — or all of them — before '
                + 'you read anything else. A truncated transfer looks exactly like a repository '
                + 'with a missing document.',
            },
            {
              id: '0.2',
              title: 'Run the gate once, before you change anything',
              detail: 'npm ci, then npm run test:node. Keep the output. It is 138 stages and should '
                + 'exit 0. Running it again at the end and diffing the two is how you know what you '
                + 'actually changed.',
            },
            {
              id: '0.3',
              title: 'Fill §0 of the execution agent brief',
              detail: 'docs/deployment/governance/EXECUTION-AGENT-BRIEF.md. Seven inputs cannot be '
                + 'derived from anything in the export. If §0.4 — the escalation recipient — is '
                + 'blank, do not start: an escalation with no recipient is a stop with no resumption.',
            },
            ...accesses().map((a, i) => ({
              id: `0.${i + 4}`,
              title: a.access,
              detail: `Prove it before you need it: ${a.provesOutBy}.`,
              isAccess: true,
            })),
          ],
        },
        ...['A', 'B', 'C', 'D'].map((L) => {
          const [rel, prefix] = RUNBOOK[L];
          return {
            id: L,
            title: by[L].title,
            why: '',
            waits: by[L].note,
            kind: 'runbook',
            document: rel,
            steps: runbookSections(rel, prefix, by[L].from, by[L].to)
              .map((s) => ({ id: s.id, title: s.title, detail: '' })),
          };
        }),
        {
          id: 'E',
          title: `The ${d.totals.open} open items`,
          /* The entry document's phase E names the executable subset in ACTION_PLAN.md. This phase
           * carries all of them — every open item across all five registers, the agency decisions
           * and the notification workstream included — so it says so rather than borrowing a count
           * that means something narrower. */
          why: 'These are not runbook sections: they are the open items themselves, grouped by who '
            + 'holds the access, each written out in full in EXTERNAL_EXECUTION.md. '
            + (by.E.names
              ? `The order diagram calls this phase "the ${by.E.names[1]} items in ${by.E.names[2]}" — `
                + `those are the ones an operator can execute, and they are ${d.totals.open - Number(by.E.names[1])} short of the whole, `
                + 'because the agency decisions and the notification workstream are here too.'
              : ''),
          waits: 'most of these close conditions the earlier phases create',
          kind: 'register',
          tracks: d.tracks.map((t) => ({
            id: t.id,
            title: t.title,
            who: t.who,
            access: t.access,
            steps: t.steps.map((s) => ({
              id: s.id,
              title: s.title,
              source: s.source,
              actor: s.actor,
              what: s.what,
              state: s.state,
              actions: s.actions,
              inputs: s.inputs,
              commands: s.commands,
              closesWhen: s.closesWhen,
              closureNotEstablished: s.closureNotEstablished,
              carryBack: s.carryBack,
              waitsOn: s.waitsOn,
              waitedOnBy: s.waitedOnBy,
              gating: (m.gatingCommissioning || []).includes(s.id),
            })),
          })),
        },
      ];

      return {
        totals: d.totals,
        gating: m.gatingCommissioning || [],
        registryStandUp: d.registryStandUp,
        phases,
      };
    },
  },
];

const built = PAGES.map((p) => {
  const tpl = read(p.template);
  if (!tpl.includes('__DATA__')) {
    console.error(`\n  ✖  ${p.template} carries no __DATA__ token — nothing would be injected.\n`);
    process.exit(2);
  }
  const html = tpl.replace('__DATA__', embed(p.data()));
  if (p.selfContained) {
    const loaders = [...html.matchAll(/(?:src|href)\s*=\s*"(https?:\/\/[^"]+)"/gi)].map((m) => m[1]);
    if (loaders.length) {
      console.error(`\n  ✖  ${p.target} is declared self-contained and loads ${loaders.length} thing(s) from the network:`);
      for (const u of loaders) console.error(`       ${u}`);
      console.error('     It is opened from a file path by someone who may have no route out. Inline it.\n');
      process.exit(2);
    }
  }
  return [p, html];
});

if (CHECK) {
  const drifted = built.filter(([p, html]) => {
    const abs = join(ROOT, p.target);
    return !existsSync(abs) || readFileSync(abs, 'utf8') !== html;
  });
  if (!drifted.length) {
    console.log(`\n  ✅ both published pages match their registers (${built.length}).\n`);
    process.exit(0);
  }
  console.error(`\n  ✖  ${drifted.map(([p]) => p.target).join(' and ')} drifted from the registers.`);
  console.error('     Run: npm run pages\n');
  process.exit(1);
}

console.log('\nPublished pages, rebuilt from the registers\n');
for (const [p, html] of built) {
  writeFileSync(join(ROOT, p.target), html);
  console.log(`  wrote ${p.target}  (${(html.length / 1024).toFixed(0)} KB)`);
  console.log(`        renders ${p.renders}`);
  console.log(`        published at ${p.published}`);
}
console.log('\n  Neither page now exists only on a host. Republish either by passing its URL to the');
console.log('  Artifact tool; the file in the branch is what was published.\n');
